package com.julesmeister.deutschcraft.core.database.entity.learninganalytics

import androidx.room.Entity
import androidx.room.Index

/*
 * Semantic interaction evidence generated by the existing
 * mission-objective Qwen evaluation request.
 *
 * One row is stored for each evaluated learner message.
 */
@Entity(
    tableName =
        "mission_interaction_evidence",
    primaryKeys = [
        "conversationMissionId",
        "messageId"
    ],
    indices = [
        Index(
            value = [
                "conversationMissionId"
            ]
        ),
        Index(
            value = [
                "messageId"
            ],
            unique =
                true
        ),
        Index(
            value = [
                "conversationMissionId",
                "evaluatedAt"
            ]
        )
    ]
)
data class MissionInteractionEvidenceEntity(
    val conversationMissionId: String,

    val messageId: String,

    val relevantReply: Boolean,

    val followUpQuestion: Boolean,

    val clarification: Boolean,

    val replyExpected: Boolean,

    val confidence: Float,

    val evaluatedAt: Long
)